"use client";
/* Snip, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Snip(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("snip"); }, []);
  return React.createElement("piix-pal", { "pal": "snip", ...piixAttrs(props) });
}

export default Snip;
